    active: "2ce40abf-777b-4f27-8b21-bd6f7cb6f001",
    sold: "2ce40abf-777b-4f27-8b21-bd6f7cb6f002",
    gifted: "2ce40abf-777b-4f27-8b21-bd6f7cb6f003",
    retired: "2ce40abf-777b-4f27-8b21-bd6f7cb6f004",
    pending: "2ce40abf-777b-4f27-8b21-bd6f7cb6f005",
