const DEFAULT_TAG_GROUP_ID = "7bfb44c9-77d7-4f01-9b20-1762976b4001";
const DEFAULT_LOOK_TAG_GROUP_ID = "8cfc55da-88e8-4012-ac31-2873087c5001";
function costPerWear(item) {
    return !item.price || item.wearCount <= 0 ? null : item.price.amount / item.wearCount;
}
function formatMoney(money) {
    if (!money)
        return "未填写";
    const amount = money.amount.toLocaleString("zh-CN", { maximumFractionDigits: Number.isInteger(money.amount) ? 0 : 2 });
    return money.currency === "JPY" ? `¥${amount} 日元` : `¥${amount} 人民币`;
}

