async function saveManualOrder(kind, visibleIds) {
    const table = db.table(kind);
    await db.transaction("rw", table, async () => {
        const all = (await table.filter((row) => !row.deletedAt).toArray())
            .sort((a, b) => (a.manualOrder ?? Number.MAX_SAFE_INTEGER) - (b.manualOrder ?? Number.MAX_SAFE_INTEGER));
        const selected = new Set(visibleIds);
        let cursor = 0;
        const merged = all.map((row) => selected.has(row.id) ? { ...row, id: visibleIds[cursor++] } : row);
        await Promise.all(merged.map((row, manualOrder) => table.update(row.id, { manualOrder })));
    });
}
