const empty = () => ({ CNY: 0, JPY: 0 });
function wardrobeTotals(items) {
    const active = empty(), pending = empty(), sold = empty();
    for (const item of items) {
        if (item.statusId === DEFAULT_STATUS_IDS.sold) {
            if (item.salePrice && Number.isFinite(item.salePrice.amount))
                sold[item.salePrice.currency] += item.salePrice.amount;
            continue;
        }
        if (item.statusId !== DEFAULT_STATUS_IDS.active && item.statusId !== DEFAULT_STATUS_IDS.pending)
            continue;
        if (item.purchase?.type === "deposit" && !item.purchase.balancePaid)
            continue;
        if (!item.price || !Number.isFinite(item.price.amount))
            continue;
        const bucket = item.statusId === DEFAULT_STATUS_IDS.active ? active : pending;
        bucket[item.price.currency] += item.price.amount;
    }
    return { total: { CNY: active.CNY + pending.CNY, JPY: active.JPY + pending.JPY }, active, pending, sold };
}

