function settingsParent(path) {
    if (path.startsWith("bulk-tag/"))
        return "settings/manage/wardrobe/tags/clothing";
    if (/^settings\/changelog\/[^/]+$/.test(path))
        return "settings/changelog";
    if (parents[path])
        return parents[path];
    if (/^settings\/manage\/[^/]+\/.+/.test(path))
        return path.slice(0, path.lastIndexOf("/"));
    if (/^settings\/manage\/[^/]+$/.test(path))
        return "settings";
    return undefined;
}
function settingsParentHref(path) {
    return `#/${settingsParent(path) ?? "settings"}`;
}

