            items: "id, name, wishlist, favorite, categoryId, paymentMode, balancePaid, balanceDueMonth, status, storageLocation, updatedAt, *tagIds",
            tags: "id, &normalizedName, groupId, sortOrder, name, updatedAt",
            categories: "id, &normalizedName, sortOrder, name, updatedAt",
            tagGroups: "id, &normalizedName, sortOrder, name, updatedAt",
            sets: "id, name, updatedAt, *itemIds",
            photos: "id, itemId, updatedAt",
            meta: "id, updatedAt",
