const circled = ["①", "②", "③", "④", "⑤", "⑥"];
function lookShareDetails(photoIds, items, tags, options) {
    return photoIds.map((photoId, index) => {
        const item = items.find((value) => value.photoIds.includes(photoId));
        const prefix = options.numbered ? circled[index] ?? `${index + 1}.` : "";
        if (!item)
            return [prefix, "搭配照片"].filter(Boolean).join(" ");
        const parts = [
            options.brand ? displayBrand(item.brand) : "",
            options.name ? item.name : "",
            options.price && item.price ? formatMoney(item.price) : "",
            options.tags ? tags.filter((tag) => item.tagIds.includes(tag.id)).map((tag) => tag.name).join("/") : "",
        ].filter(Boolean);
        return [prefix, parts.join(" · ")].filter(Boolean).join(" ");
    });
}

