async function addLookPhotos(lookId, values) {
    const look = await db.looks.get(lookId);
    if (!look || look.deletedAt)
        throw new Error("请先保存搭配");
    const existing = await db.lookPhotos.where("lookId").equals(lookId).filter((photo) => !photo.deletedAt).count();
    const timestamp = nowIso();
    const records = values.map((value, index) => {
        const id = newId();
        const photo = { id, lookId, sortOrder: existing + index, displayMimeType: value.displayBlob.type,
            thumbnailMimeType: value.thumbnailBlob.type, width: value.width, height: value.height,
            thumbnailWidth: value.thumbnailWidth, thumbnailHeight: value.thumbnailHeight,
            displayBytes: value.displayBlob.size, thumbnailBytes: value.thumbnailBlob.size, createdAt: timestamp, updatedAt: timestamp };
        const assets = [
            { id: `${id}:display`, photoId: id, kind: "display", blob: value.displayBlob },
            { id: `${id}:thumbnail`, photoId: id, kind: "thumbnail", blob: value.thumbnailBlob },
        ];
        return { photo, assets };
    });
    await db.transaction("rw", db.lookPhotos, db.photoAssets, async () => {
        await db.lookPhotos.bulkAdd(records.map((row) => row.photo));
        await db.photoAssets.bulkAdd(records.flatMap((row) => row.assets));
    });
    return records.map((row) => row.photo);
}
async function removeLookPhoto(id) {
    const timestamp = nowIso();
    await db.transaction("rw", db.lookPhotos, db.looks, async () => {
        const photo = await db.lookPhotos.get(id);
        if (!photo)
            return;
        await db.lookPhotos.update(id, { deletedAt: timestamp, updatedAt: timestamp });
        const look = await db.looks.get(photo.lookId);
        if (look)
            await db.looks.update(photo.lookId, { previewCells: look.previewCells?.filter((cell) => cell.photoId !== id), updatedAt: timestamp });
    });
}

