async function restoreCollectionBackup(preview, selection, mode, choices = {}, onProgress) {
    const verified = await inspectCollectionBackup(preview.file, onProgress);
    if (!selection.wardrobe && !selection.goods)
        throw new Error("请至少选择一个模块");
    if (selection.wardrobe && !verified.wardrobe)
        throw new Error("备份没有衣柜内容");
    if (selection.goods && !verified.goods)
        throw new Error("备份没有 Goods 内容");
    const oldGoods = selection.goods && selection.wardrobe ? await captureGoodsBackup() : undefined;
    let goodsWritten = false;
    try {
        if (selection.goods && verified.goods) {
            onProgress?.(mode === "merge" ? "正在合并 Goods…" : "正在恢复 Goods…");
            await restoreGoodsBackup(verified.goods, mode);
            goodsWritten = true;
        }
        if (selection.wardrobe && verified.wardrobe) {
            onProgress?.(mode === "merge" ? "正在合并衣柜…" : "正在恢复衣柜…");
            if (mode === "merge")
                await mergeBackup(verified.wardrobe, choices, onProgress);
            else
                await restoreBackup(verified.wardrobe, onProgress);
        }
    }
    catch (error) {
        if (goodsWritten && oldGoods) {
            try {
                await restoreGoodsBackup(oldGoods, "overwrite");
            }
            catch {
                throw new Error("恢复中断且 Goods 自动回退失败，请保留原备份并停止操作");
            }
        }
        throw error;
    }
}
